// SymForce runner for the 2D pose-graph benchmark -- the generated-code
// path: the shared rotation-frame residual is defined symbolically in
// ../symforce_gen.py, code-generated by SymForce into flattened C++
// linearization functions (symforce_gen/{between,prior}_factor.h), and
// executed by SymForce's own C++ sym::Optimizer (LM). Templated over
// double/float: SymForce supports both precisions natively.
//
//   symforce_bench <file.g2o> <f64|f32> <poses_out> <info|unit>
//
// JSON {solve_ms, first_iter_ms, iterations, accepted, cpus_allowed} on
// stdout, "x y theta" lines to poses_out. SYMFORCE_LAMBDA0 overrides the
// initial damping (default 1e-10 per the README's initial-damping
// policy; SymForce ships 1.0).

#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include <sym/pose2.h>
#include <sym/util/epsilon.h>
#include <symforce/opt/factor.h>
#include <symforce/opt/key.h>
#include <symforce/opt/optimizer.h>

#include "symforce_gen/between_factor.h"
#include "symforce_gen/prior_factor.h"

struct PoseIn {
    double x, y, th;
};
struct EdgeIn {
    int a, b;
    double dx, dy, dth;
    double wt, wr;
};

static void parse_g2o(const char* path, bool unit, std::vector<PoseIn>& poses, std::vector<EdgeIn>& edges) {
    std::ifstream f(path);
    std::string line;
    while (std::getline(f, line)) {
        std::istringstream ss(line);
        std::string tag;
        ss >> tag;
        if (tag == "VERTEX_SE2") {
            int id;
            PoseIn p;
            ss >> id >> p.x >> p.y >> p.th;
            poses.push_back(p);
        } else if (tag == "EDGE_SE2") {
            EdgeIn e;
            double i11, i12, i13, i22, i23, i33;
            ss >> e.a >> e.b >> e.dx >> e.dy >> e.dth >> i11 >> i12 >> i13 >> i22 >> i23 >> i33;
            e.wt = unit ? 1.0 : std::sqrt(i11);
            e.wr = unit ? 1.0 : std::sqrt(i33);
            edges.push_back(e);
        }
    }
}

struct RunResult {
    double ms;
    int accepted, total;
};

template <typename Scalar>
RunResult solve(const std::vector<PoseIn>& poses, const std::vector<EdgeIn>& edges,
                int max_iters, std::vector<PoseIn>* out) {
    sym::Values<Scalar> values;
    for (size_t i = 0; i < poses.size(); i++) {
        values.Set({'P', (int64_t)i},
                   sym::Pose2<Scalar>(sym::Rot2<Scalar>::FromAngle((Scalar)poses[i].th),
                                      Eigen::Matrix<Scalar, 2, 1>((Scalar)poses[i].x, (Scalar)poses[i].y)));
    }
    for (size_t k = 0; k < edges.size(); k++) {
        const EdgeIn& e = edges[k];
        values.Set({'x', (int64_t)k}, (Scalar)e.dx);
        values.Set({'y', (int64_t)k}, (Scalar)e.dy);
        values.Set({'t', (int64_t)k}, (Scalar)e.dth);
        values.Set({'u', (int64_t)k}, (Scalar)e.wt);
        values.Set({'v', (int64_t)k}, (Scalar)e.wr);
    }
    values.Set({'a'}, (Scalar)poses[0].x);
    values.Set({'b'}, (Scalar)poses[0].y);
    values.Set({'c'}, (Scalar)poses[0].th);
    values.Set({'e'}, sym::kDefaultEpsilon<Scalar>);

    std::vector<sym::Factor<Scalar>> factors;
    factors.reserve(edges.size() + 1);
    for (size_t k = 0; k < edges.size(); k++) {
        const EdgeIn& e = edges[k];
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::BetweenFactor<Scalar>,
            {{'P', e.a}, {'P', e.b}, {'x', (int64_t)k}, {'y', (int64_t)k}, {'t', (int64_t)k},
             {'u', (int64_t)k}, {'v', (int64_t)k}, {'e'}},
            {{'P', e.a}, {'P', e.b}}));
    }
    factors.push_back(sym::Factor<Scalar>::Hessian(
        sym::PriorFactor<Scalar>, {{'P', 0}, {'a'}, {'b'}, {'c'}, {'e'}}, {{'P', 0}}));

    auto params = sym::DefaultOptimizerParams();
    params.iterations = max_iters;
    // Same termination class as the other systems.
    params.early_exit_min_reduction = 1e-5;
    // Problem-appropriate initial damping (see the README policy;
    // SymForce ships initial_lambda = 1.0).
    params.initial_lambda = 1e-10;
    if (const char* l = getenv("SYMFORCE_LAMBDA0")) {
        params.initial_lambda = atof(l);
    }

    sym::Optimizer<Scalar> optimizer(params, std::move(factors));
    auto t0 = std::chrono::steady_clock::now();
    auto stats = optimizer.Optimize(values);
    double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();

    int accepted = 0;
    for (const auto& it : stats.iterations) {
        if (it.update_accepted) accepted++;
    }
    if (out) {
        out->resize(poses.size());
        for (size_t i = 0; i < poses.size(); i++) {
            const auto p = values.template At<sym::Pose2<Scalar>>({'P', (int64_t)i});
            (*out)[i] = PoseIn{(double)p.Position()[0], (double)p.Position()[1],
                               (double)p.Rotation().ToAngle(sym::kDefaultEpsilon<Scalar>)};
        }
    }
    return RunResult{ms, accepted, (int)stats.iterations.size()};
}

template <typename Scalar>
void run(const char* g2o, const char* poses_out, bool unit) {
    std::vector<PoseIn> poses;
    std::vector<EdgeIn> edges;
    parse_g2o(g2o, unit, poses, edges);

    RunResult first = solve<Scalar>(poses, edges, 1, nullptr);
    std::vector<PoseIn> result;
    RunResult full = solve<Scalar>(poses, edges, 100, &result);

    std::ofstream out(poses_out);
    for (const PoseIn& p : result) {
        out << p.x << " " << p.y << " " << p.th << "\n";
    }
    std::string cpus = "?";
    std::ifstream st("/proc/self/status");
    std::string l;
    while (std::getline(st, l)) {
        if (l.rfind("Cpus_allowed_list:", 0) == 0) {
            cpus = l.substr(l.find_last_of(" \t") + 1);
        }
    }
    printf("{\"solve_ms\": %.3f, \"first_iter_ms\": %.3f, \"iterations\": %d, \"accepted\": %d, \"cpus_allowed\": \"%s\"}\n",
           full.ms, first.ms, full.total, full.accepted, cpus.c_str());
}

int main(int argc, char** argv) {
    // Silence SymForce's atexit profiling table (it would interleave
    // with the JSON protocol line on stdout).
    setenv("SYMFORCE_TIC_TOC_QUIET", "1", 0);
    if (argc < 5) { fprintf(stderr, "usage: %s <g2o> <f64|f32> <poses_out> <info|unit>\n", argv[0]); return 1; }
    bool unit = std::string(argv[4]) == "unit";
    if (std::string(argv[2]) == "f32") {
        run<float>(argv[1], argv[3], unit);
    } else {
        run<double>(argv[1], argv[3], unit);
    }
    return 0;
}
